import java.util.*;

class Notification{
    String name;
    int len;
    Notification(String n,int l){
        name = n;
        len = l;
    }
}

class Email extends Notification{
    float cost;
    Email(String n,int l){
        super(n,l);
    }
    void calc(){
        cost = (float)len * 0.10f;
    }
    void display(){
        System.out.println("Notification sent to: "+name);
        System.out.printf("Total Cost: %.1f",cost);
    }
}

class SMS extends Notification{
    float cost;
    SMS(String n,int l){
        super(n,l);
    }
    void calc(){
        cost = 5.0f + (float)len * 1.5f + 2;
    }

    void display(){
        System.out.println("Notification sent to: "+name);
        System.out.printf("Total Cost: %.1f",cost);
    }
}

class Main{
    public static void main(String arg[]){
        Scanner sc = new Scanner(System.in);
        String type = sc.nextLine();
        String name = sc.nextLine();
        int len = sc.nextInt();

        if(name.chars().anyMatch(Character::isDigit) || name.length() == 0){
                System.out.printf("Invalid Input");
                return;
            }
        else if(len<0){
            System.out.printf("Invalid Input");
                return;
        }
        else if(type.equals("Email")){
            Email e = new Email(name,len);
            e.calc();
            e.display();
        }
        else if(type.equals("SMS")){
            SMS s = new SMS(name,len);
            s.calc();
            s.display();
        }
        else{
            System.out.printf("Invalid Input");
        }
    }
}

